SELECT c.policy_id, p.region, SUM(CASE WHEN c.status = 'CLOSED' THEN COALESCE(c.paid_amount, 0) ELSE 0 END) AS closed_paid, COUNT(DISTINCT c.claim_id) AS claim_count, ROW_NUMBER() OVER (PARTITION BY c.policy_id ORDER BY c.claim_date DESC) AS recency, SUM(c.paid_amount) OVER (PARTITION BY p.region ORDER BY c.claim_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_paid FROM claims AS c INNER JOIN policies AS p ON p.policy_id = c.policy_id INNER JOIN customers AS u ON u.customer_id = p.customer_id WHERE c.claim_id >= 'CL000034' GROUP BY c.policy_id, p.region;
